def majority_element(seq):
    candidate = None
    count = 0
    for x in seq:
        if count == 0:
            candidate = x
            count = 1
        elif x == candidate:
            count += 1
        else:
            count -= 1
    if candidate is None:
        return None
    if seq.count(candidate) * 2 > len(seq):
        return candidate
    return None

def sum_proper_divisors(n):
    if n <= 1:
        return 0
    total = 1
    i = 2
    while i * i <= n:
        if n % i == 0:
            total += i
            if i != n // i:
                total += n // i
        i += 1
    return total

