def is_valid_dice_notation(s):
    import re
    m = re.fullmatch(r'(\d+)d(\d+)', s)
    if not m:
        return False
    n, sides = m.groups()
    for p in (n, sides):
        if len(p) > 1 and p[0] == '0':
            return False
        if int(p) == 0:
            return False
    return True
